#include <iostream>
#include <string>
using namespace std;

int main() {
    string months[] = {
        "January", "February", "March", "April",
        "May", "June", "July", "August",
        "September", "October", "November", "December"
    };

    string s;
    long long k;
    cin >> s >> k;

    int m = 0;
    while (months[m] != s) {
        ++m;
    }

    int result = static_cast<int>((m + k) % 12);
    if (result < 0) result += 12;

    cout << months[result];
    return 0;
}

